// ❌ OLD: The old mutation events (DOMNodeInserted, DOMAttrModified,
// etc.) fired SYNCHRONOUSLY for every single DOM change. A loop that
// inserts 10,000 nodes triggers 10,000 handler calls in the middle of
// the work — and mutating inside the handler re-triggers the event,
// which is why they caused infinite loops and jank.
document.addEventListener('DOMNodeInserted', (e) => {
  // ❌ OLD: runs inline during the insertion — blocks rendering,
  // and DOM mutation here can re-fire the event recursively.
  console.log('node added', e.target);
});

// Deprecated and removed from browsers; still appears in old codebases.

// ✅ NEW: MutationObserver batches all mutations that occur in a
// synchronous block and delivers them ONCE in a microtask. The callback
// receives a full array of MutationRecords.
const obs = new MutationObserver((records) => {
  // ✅ NEW: records is the complete batched list — process once, not
  // once per mutation.
  for (const rec of records) {
    console.log('added', rec.addedNodes, 'to', rec.target);
  }
});

obs.observe(root, { childList: true, subtree: true });

// Insert 10,000 nodes in one loop: the observer fires ONCE after the
// current task, with 10,000 records — no per-mutation jank.
for (let i = 0; i < 10_000; i++) {
  root.append(document.createElement('div'));
}

// Later: obs.disconnect() to stop observing and release the target.
